@@ -317,2 +317,14 @@
-fn strip_twos3(u: &mut [u64; 3]) -> u32 {
-    let mut removed = 0;
+fn strip_twos3(u: &mut [u64; 3]) -> u32 {
+    let shift = u[0].trailing_zeros();
+    if shift == 0 {
+        return 0;
+    }
+    if shift < 64 {
+        *u = [
+            (u[0] >> shift) | (u[1] << (64 - shift)),
+            (u[1] >> shift) | (u[2] << (64 - shift)),
+            u[2] >> shift,
+        ];
+        return shift;
+    }
+    let mut removed = 0;

